         L     3,4(0,1)            A(physical line)
         L     4,8(0,1)            A(target line)
         L     5,12(0,1)           A(buffer)
         L     9,16(0,1)           A(pending control)
         L     10,20(0,1)          A(LINE-COUNTER)
         L     11,24(0,1)          A(this report's blank line)
