UNS170   L     14,0(6)             receiver
         LH    15,4(6)             its length
         MVI   0(14),C' '
         LR    11,15
         BCTR  11,0
         LTR   11,11
         BZ    UNS172              a one-byte receiver is filled
         BCTR  11,0
         EX    11,UNSPAD           space fill
UNS172   LR    1,8
         SR    1,4                 bytes to move
         L     11,12(6)            COUNT IN cell
         LTR   11,11
         BZ    UNS174
         ST    1,0(11)             the count, before truncation
UNS174   CR    1,15
         BNH   UNS176
         LR    1,15                truncated on the right
UNS176   LTR   1,1
         BZ    UNS180              nothing to move
         BCTR  1,0
         LA    15,0(3,4)
         EX    1,UNSMVC            the bytes
UNS180   L     14,8(6)             DELIMITER IN
         LTR   14,14
         BZ    UNS186
         LH    15,6(6)             its length
         MVI   0(14),C' '
         LR    11,15
         BCTR  11,0
         LTR   11,11
         BZ    UNS182
         BCTR  11,0
         EX    11,UNSPAD           space fill
UNS182   LTR   9,9
         BZ    UNS186              no delimiter: spaces
         LH    1,4(9)              delimiter length
         CR    1,15
         BNH   UNS184
         LR    1,15
UNS184   BCTR  1,0
         L     15,0(9)
         EX    1,UNSMVC            the delimiter
UNS186   L     14,12(2)            TALLYING cell
         LTR   14,14
         BZ    UNS188
         L     15,0(14)
         LA    15,1(15)            one more receiver acted on
         ST    15,0(14)
UNS188   LTR   9,9
         BZ    UNS196              no delimiter: position is where the
         LH    1,4(9)              delimiter length
         LA    4,0(1,8)            past the delimiter
         LH    0,6(9)              ALL?
         LTR   0,0
         BZ    UNS198
UNS190   LR    0,5
         SR    0,4                 bytes left
         CR    0,1
         BL    UNS198              not enough for another copy
         LA    15,0(3,4)
         L     14,0(9)
         LR    11,1
         BCTR  11,0
         EX    11,UNSCLC2          another copy of the delimiter?
         BNE   UNS198
         LA    4,0(1,4)            skip it too
         B     UNS190
UNS196   LR    4,8
UNS198   LA    6,16(6)             next receiver
         BCTR  7,0
         B     UNS100
UNSEND   SR    15,15
         CR    4,5
         BNL   UNS200
         LA    15,1                bytes left over: overflow
UNS200   L     14,8(2)             pointer cell
         LTR   14,14
         BZ    UNSX
         LA    4,1(4)
         ST    4,0(14)
         B     UNSX
UNSBAD   LA    15,1                pointer out of range: overflow, noth
UNSX     L     13,4(13)
         ST    15,16(13)           R15 survives the LM through its own
         LM    14,12,12(13)
         BR    14
UNSCLC   CLC   0(0,1),0(14)        executed with the delimiter length
UNSCLC2  CLC   0(0,15),0(14)
UNSMVC   MVC   0(0,14),0(15)       executed with the byte count
UNSPAD   MVC   1(0,14),0(14)       executed: propagate the space
RTSAVE9  DS    18F
*
* COBWTO -- DISPLAY UPON CONSOLE. R1 -> A(text), A(halfword length).
* The text goes into a WTO list whose length halfword is set
* from the parameter; MVS caps a line at what it will show.
COBWTO   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE10+4
         LA    11,RTSAVE10
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(text)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)
         CH    4,WTOMAX
         BNH   WTO010
         LH    4,WTOMAX
WTO010   MVI   WTOTXT,C' '
         MVC   WTOTXT+1(119),WTOTXT
         LTR   4,4
         BNP   WTO020
         BCTR  4,0
         EX    4,WTOMVC
         LA    4,1(4)
WTO020   LA    4,4(4)              plus the header
         STH   4,WTOLST
         WTO   MF=(E,WTOLST)
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
WTOMVC   MVC   WTOTXT(0),0(2)      executed
WTOMAX   DC    H'120'
WTOLST   DC    AL2(124),AL2(0)     length, MCS flags
WTOTXT   DC    CL120' '
RTSAVE10 DS    18F
*
* COBWTOR -- ACCEPT FROM CONSOLE. R1 -> A(item), A(halfword length).
* A WTOR asks the operator, the task waits on its ECB, and the
* reply is moved to the item space padded. One line only.
COBWTOR  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE11+4
         LA    11,RTSAVE11
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(item)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)
         MVI   WTORRPL,C' '
         MVC   WTORRPL+1(119),WTORRPL
         XC    WTORECB,WTORECB
         WTOR  'COBC370: ACCEPT FROM CONSOLE',WTORRPL,120,WTORECB
         WAIT  ECB=WTORECB
         LTR   4,4
         BNP   WTOR20
         CH    4,WTORMAX
         BNH   WTOR10
         LH    4,WTORMAX
WTOR10   BCTR  4,0
         EX    4,WTORMVC
WTOR20   L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
WTORMVC  MVC   0(0,2),WTORRPL      executed
WTORMAX  DC    H'120'
WTORECB  DC    F'0'
WTORRPL  DC    CL120' '
RTSAVE11 DS    18F
*
* COBADT -- ACCEPT FROM DATE, DAY or TIME. R1 -> A(area), A(halfword
* kind: 1 DATE, 2 DAY, 3 TIME). Writes YYMMDD, YYDDD or HHMMSSth as
* zoned digits into the area. DATE borrows COBDATE's month walk.
COBADT   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE12+4
         LA    11,RTSAVE12
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            the area
         L     3,4(0,1)
         LH    3,0(0,3)            the kind
         CH    3,ADTH3
         BE    ADT300              TIME
         TIME  DEC                 R1 = 00YYDDDF
         ST    1,ADTPK
         UNPK  ADTZ(7),ADTPK(4)    '00YYDDD'
         OI    ADTZ+6,X'F0'
         CH    3,ADTH2
         BE    ADT200              DAY
         LA    1,ADTB              DATE: MM/DD/YY first
         L     15,ADTVD
         BALR  14,15
         MVC   0(2,2),ADTB+6       YY
         MVC   2(2,2),ADTB         MM
         MVC   4(2,2),ADTB+3       DD
         B     ADTX
ADT200   MVC   0(5,2),ADTZ+2       YYDDD
         B     ADTX
ADT300   TIME  DEC                 R0 = HHMMSSth
         ST    0,ADTPK
         MVI   ADTPK+4,X'0F'       a sign nibble to unpack against
         UNPK  ADTZ(9),ADTPK(5)    'HHMMSSth0'
         MVC   0(8,2),ADTZ
ADTX     L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
ADTVD    DC    A(COBDATE)
ADTH2    DC    H'2'
ADTH3    DC    H'3'
ADTPK    DS    2F
ADTZ     DS    CL9
ADTB     DS    CL8
RTSAVE12 DS    18F
*
* COBDCAL -- CALL identifier. R1 -> A(8-byte name), A(parameter list).
* A table of programs loaded so far: a name found there is called
* at the entry point remembered; one not found is LOADed and
* remembered, so each program is loaded once until CANCELled.
* The callee's return code comes back in R15.
COBDCAL  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE14+4
         LA    11,RTSAVE14
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            the name
         L     3,4(0,1)            the parameter list
         LA    4,DCTAB
         LA    5,16                entries
         SR    6,6                 no hole yet
DCA010   CLC   0(8,4),0(2)         this one?
         BE    DCA030              already loaded
         CLI   0(4),X'00'          an empty entry?
         BNE   DCA020
         LTR   6,6
         BNZ   DCA020              keep the first hole
         LR    6,4
DCA020   LA    4,12(4)
         BCT   5,DCA010
         LTR   6,6                 a hole to remember this load?
         BZ    DCAFULL             table full
         LR    4,6
         B     DCA050
DCAFULL  LOAD  EPLOC=(2)           table full: load without remembering
         LR    15,0
         B     DCA040
DCA050   MVC   0(8,4),0(2)         remember the name
         LOAD  EPLOC=(2)
         ST    0,8(0,4)            and the entry point
DCA030   L     15,8(0,4)
DCA040   LR    1,3                 R1 -> the callee's parameters
         BALR  14,15
         L     13,4(13)
         ST    15,16(13)           the callee's return code survives th
         LM    14,12,12(13)
         BR    14
RTSAVE14 DS    18F
*
* COBCANC -- CANCEL. R1 -> A(8-byte name). A program in the table is
* DELETEd and forgotten; one that is not is left alone.
COBCANC  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE15+4
         LA    11,RTSAVE15
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            the name
         LA    4,DCTAB
         LA    5,16
CAN010   CLI   0(4),X'00'
         BE    CANNEXT             empty: keep looking
         CLC   0(8,4),0(2)
         BE    CAN020
CANNEXT  LA    4,12(4)
         BCT   5,CAN010
         B     CANX
CAN020   DELETE EPLOC=(2)          release it
         XC    0(12,4),0(4)        and forget it
CANX     L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
DCTAB    DC    16XL12'00'          loaded programs: CL8 name, A(entry)
RTSAVE15 DS    18F
*
* COBMVL -- an alphanumeric move of any length. R1 -> A(receiver),
*   A(sender), A(halfword receiver length, halfword sender length).
* The shorter of the two is moved in 256-byte pieces; a receiver
* longer than the sender is space filled after it. Serves a group
* whose length depends on an OCCURS DEPENDING ON count, and any
* move too long for one MVC.
COBMVL   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE13+4
         LA    11,RTSAVE13
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            receiver
         L     3,4(0,1)            sender
         L     4,8(0,1)
         LH    5,0(0,4)            receiver length
         LH    6,2(0,4)            sender length
         LR    7,5
         CR    7,6
         BNH   MVL010
         LR    7,6                 bytes to move: the shorter
MVL010   SR    5,7                 bytes to fill afterwards
MVL020   LTR   7,7
         BNP   MVL040              moved
         LR    8,7
         CH    8,MVL256
         BNH   MVL030
         LH    8,MVL256            a piece
MVL030   BCTR  8,0
         EX    8,MVLMVC
         LA    8,1(8)
         AR    2,8
         AR    3,8
         SR    7,8
         B     MVL020
MVL040   LTR   5,5
         BNP   MVLX                nothing to fill
         MVI   0(2),C' '
         BCTR  5,0
MVL050   LTR   5,5
         BNP   MVLX
         LR    8,5
         CH    8,MVL256
         BNH   MVL060
         LH    8,MVL256
MVL060   BCTR  8,0
         EX    8,MVLPAD            propagate the space
         LA    8,1(8)
         AR    2,8
         SR    5,8
         B     MVL050
MVLX     L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
MVLMVC   MVC   0(0,2),0(3)         executed
MVLPAD   MVC   1(0,2),0(2)         executed
MVL256   DC    H'256'
RTSAVE13 DS    18F
         END
